from pathlib import Path; import json,math,numpy as np
out=Path(__file__).parent; rows=json.loads((out/'e2-decoded-predictions.json').read_text())['rows']; quant={'identity':lambda a:a,'floor':np.floor,'nearest':lambda a:np.floor(a+.5)}; formulas={'full':lambda a,b:255*a+b*(1-a),'terms_floor':lambda a,b:np.floor(255*a)+np.floor(b*(1-a)),'terms_nearest':lambda a,b:np.floor(255*a+.5)+np.floor(b*(1-a)+.5),'float32':lambda a,b:float(np.float32(np.float32(255)*np.float32(a))+np.float32(np.float32(b)*np.float32(np.float32(1)-np.float32(a))))}; controls=[{'pixel':[428,324],'B':93,'native':93,'web':93,'gpu_alpha_bytes':[0]*4,'exact_alpha_bytes':[0]*4,'weights':[1,0,0,0]},{'pixel':[431,321],'B':93,'native':255,'web':255,'gpu_alpha_bytes':[255]*4,'exact_alpha_bytes':[255]*4,'weights':[1,0,0,0]}]; allrows=rows+controls
trials=[{'texture':tex,'alpha_quantization':aq,'blend':name,'convert':conv,'predictions':[int(quant[conv](fun(float(q(float(np.dot(r['weights'],r[tex]))))/255,r['B']))) for r in allrows]} for tex in ['gpu_alpha_bytes','exact_alpha_bytes'] for aq,q in quant.items() for name,fun in formulas.items() for conv in ['floor','nearest']]
[t.update({'native_mismatches':sum(a!=r['native'] for a,r in zip(t['predictions'][:14],rows)),'web_mismatches':sum(a!=r['web'] for a,r in zip(t['predictions'][:14],rows)),'control_mismatches':sum(a!=r['native'] for a,r in zip(t['predictions'][14:],controls))}) for t in trials]
(out/'e4-blend-rules.json').write_text(json.dumps({'rows_order':[r['pixel'] for r in allrows],'controls':controls,'trials':trials},indent=2),encoding='utf8'); print(sorted([{k:v for k,v in t.items() if k!='predictions'} for t in trials],key=lambda t:t['native_mismatches'])[:8])
